// Generar lista de fechas objetivo (hoy+30, hoy+7, hoy+3)
const today = new Date();
const targets = [30, 7, 3].map(days => {
  const d = new Date(today);
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
});
return [{ json: { targetDates: targets, today: today.toISOString() } }];

// Para cada reserva, calcular días hasta el evento
const today = new Date();
today.setHours(0,0,0,0);

return items.map(item => {
  const eventDate = new Date(item.json.event_date);
  eventDate.setHours(0,0,0,0);
  const diffMs = eventDate - today;
  const daysUntil = Math.round(diffMs / (1000*60*60*24));

  return {
    json: {
      ...item.json,
      daysUntil,
      remaining: parseFloat(item.json.remaining || 0),
      totalPrice: parseFloat(item.json.total_price || 0),
    }
  };
});

// Merge token data with reservation data and build email content
const tokenData = items[0].json;
const reservationData = $('EnriquecerDatos').item.json;

const daysUntil = reservationData.daysUntil;
let subject, urgencyText, ultimatumHtml;

if (daysUntil <= 3) {
  subject = '⚠️ Último aviso: completa el pago de tu reserva HappyHub';
  urgencyText = 'Este es el último recordatorio';
  ultimatumHtml = '<p style="color:#dc2626;font-weight:bold">Si no realizas el pago en las próximas 48 horas, tu reserva quedará cancelada y la fecha liberada.</p>';
} else if (daysUntil <= 7) {
  subject = 'Faltan 7 días — completa el pago de tu reserva HappyHub';
  urgencyText = 'Queda poco para tu evento';
  ultimatumHtml = '';
} else {
  subject = 'Recuerda completar el pago de tu reserva HappyHub';
  urgencyText = 'Tu evento se acerca';
  ultimatumHtml = '';
}

const eventDate = new Date(reservationData.event_date).toLocaleDateString('es-ES', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

const emailBody = `<div style="font-family:sans-serif;max-width:600px;margin:0 auto;padding:20px"><h1 style="color:#7c3aed">HappyHub</h1><h2 style="color:#1f2937">${urgencyText}</h2><p>Hola <strong>${reservationData.name}</strong>,</p><p>Tienes un pago pendiente para tu reserva del <strong>${eventDate}</strong>.</p><table style="background:#f9fafb;border-radius:12px;padding:16px;width:100%;margin:20px 0"><tr><td style="color:#6b7280">Total del evento</td><td style="text-align:right">${reservationData.totalPrice.toFixed(2)} €</td></tr><tr><td style="color:#059669">Paga y señal abonada</td><td style="text-align:right;color:#059669">− ${parseFloat(reservationData.deposit_paid).toFixed(2)} €</td></tr><tr style="font-weight:bold;font-size:18px"><td>Restante a pagar</td><td style="text-align:right;color:#7c3aed">${reservationData.remaining.toFixed(2)} €</td></tr></table>${ultimatumHtml}<a href="${tokenData.url}" style="display:block;background:#7c3aed;color:white;text-align:center;padding:16px 24px;border-radius:12px;text-decoration:none;font-weight:bold;font-size:18px;margin:24px 0">Pagar ${reservationData.remaining.toFixed(2)} € con tarjeta →</a><p style="color:#6b7280;font-size:14px">Este enlace es válido durante 72 horas.</p><p style="color:#6b7280;font-size:14px">¿Tienes alguna duda? Contáctanos por <a href="https://wa.me/34624645517">WhatsApp</a> o email a <a href="mailto:hola@happyhub.es">hola@happyhub.es</a>.</p><hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0"><p style="color:#9ca3af;font-size:12px">HappyHub · C/ Rovellat, 27, Esplugues de Llobregat</p></div>`;

return [{ json: { ...reservationData, paymentUrl: tokenData.url, subject, emailBody, daysUntil } }];
